    /// <summary>
    /// For charge through SO, if settlement discount exclude charges parameter is Yes
    /// recalculate the settlement discount exluding any charges when creating the CustTransCashDisc record
    /// Didn't need the change the pending vendor invoice side (VendTransCashDisc) calc as the std code is overwritting the calculated value with cashDiscAmount
    /// which is initialize from the vendInvoiceJour.cashDisc already updated from the PurchTotals change
    /// </summary>
    /// <param name = "_custVendTransOpen">customer or vendor open transaction</param>
    protected void createCustVendTransCashDisc(CustVendTransOpen _custVendTransOpen)
    {
        next createCustVendTransCashDisc(_custVendTransOpen);

        METVendParameters metVendParameters = METVendParameters::find();

        // Only when metVendParameters.SettlementDiscChargeExclusion = Yes and for CT sales orders
        if (common 
        &&  metVendParameters.SettlementDiscChargeExclusion
        &&  SalesTable::find(CustInvoiceJour::findRecId(custVendInvoiceJour.RecId).SalesId).METSalesOrderType == metVendParameters.SalesOrderType)
        {
            // <GIN>
            if (TaxWithholdParameters_IN::checkTaxParameters())
            {
                // exclude withholding tax
                amountCur = amountCur - taxWithholdDiscAmount;
            }
            // </GIN>
          
            CustTransCashDisc custTransCashDisc;
            int cashDiscDays;
            switch (common.TableId)
            {              
                case tableNum(SalesTable),
                    tableNum(CustInvoiceTable),
                    tableNum(ProjInvoiceJour) :
                    if (cashDiscCode)
                    {
                        cashDiscDays = CashDisc::cashDiscDate(cashDiscCode, transDate) - transDate;

                        CustInvoiceJour custInvoiceJourLocal = custVendInvoiceJour;

                        // <GIN>
                        if (TaxParameters::checkTaxParameters_IN() &&
                                        CustParameters::find().CashDiscVAT)
                        {
                            custTransCashDisc = custTransCashDisc.calcCashDisc(
                                            _custVendTransOpen.company(),
                                            currencyCode,
                                            LedgerJournalCashDiscService::baseAmountCashDisc(
                                                ModuleCustVend::Cust,
                                                // CB411_412_ChargeThrough
                                                //CustVendTransCashDisc::amountExclTax(amountCur, custVendInvoiceJour.SumTax),
                                                CustVendTransCashDisc::amountExclTax(amountCur, custVendInvoiceJour.SumTax) - custInvoiceJourLocal.SumMarkup,
                                                custVendInvoiceJour.SumTax,
                                                CashDisc::find(cashDiscCode).Percent),
                                            dueDate,
                                            cashDiscDate - cashDiscDays,
                                            cashDiscCode,
                                            _custVendTransOpen.TableId,
                                            _custVendTransOpen.RecId);

                            custTransCashDisc.CashDiscAmount = cashDiscAmount;
                            custTransCashDisc.CashDiscdate   = cashDiscDate;
                            custTransCashDisc.update();
                        }
                        else
                        {
                            // </GIN>
                            /*using (TaxIntegrationTaxJurisdictionParametersContext taxIntegrationTaxJurisdictionParametersContext = TaxIntegrationTaxJurisdictionParametersContext::construct(custVendInvoiceJour.TableId, custVendInvoiceJour.RecId))
                            {*/
                            custTransCashDisc.calcCashDisc(
                                        _custVendTransOpen.company(),
                                        currencyCode,
                                        LedgerJournalCashDiscService::baseAmountCashDisc(
                                            ModuleCustVend::Cust,
                                            // CB411_412_ChargeThrough
                                            //CustVendTransCashDisc::amountExclTax(amountCur, custVendInvoiceJour.SumTax),
                                            CustVendTransCashDisc::amountExclTax(amountCur, custVendInvoiceJour.SumTax) - custInvoiceJourLocal.SumMarkup,
                                            custVendInvoiceJour.SumTax,
                                            CashDisc::find(cashDiscCode).Percent),
                                        dueDate,
                                        cashDiscDate - cashDiscDays,
                                        cashDiscCode,
                                        _custVendTransOpen.TableId,
                                        _custVendTransOpen.RecId);
                            //}
                            // <GIN>
                        }
                        // </GIN>

                        _custVendTransOpen.setCashDisc(cashDiscDate);
                        _custVendTransOpen.reread();
                        _custVendTransOpen.update();
                    }
                    break;
            }
        }
    }
